import { Link } from 'react-router-dom';

const Footer = () => {
  // Common style for links to ensure consistency
  const linkStyle = {
    display: 'block',
    fontSize: '14px', // Slightly larger for better readability
    color: 'var(--eco-text-secondary)',
    marginBottom: '10px',
    textDecoration: 'none',
    transition: 'color 0.2s ease', // Smooth professional transition
  };

  const sectionHeaderStyle = {
    fontWeight: 700,
    fontSize: '12px',
    color: 'var(--eco-text)',
    marginBottom: '20px', // More breathing room
    textTransform: 'uppercase',
    letterSpacing: '1px', // Professional tracking
  };

  return (
    <footer style={{
      background: 'var(--eco-surface)',
      borderTop: '1px solid var(--eco-border)',
      padding: '64px 24px 32px', // Increased top padding for a premium feel
      marginTop: 'auto',
    }}>
      <div style={{ maxWidth: 1100, margin: '0 auto' }}>
        <div style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))',
          gap: '40px',
          marginBottom: '48px'
        }}>

          {/* Brand & Mission */}
          <div style={{ maxWidth: '280px' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '10px', marginBottom: '16px' }}>
              <div style={{
                width: '36px',
                height: '36px',
                background: 'var(--eco-primary)',
                borderRadius: '10px',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                fontSize: '18px',
                boxShadow: '0 4px 12px rgba(var(--eco-primary-rgb), 0.2)' // Subtle depth
              }}>🌿</div>
              <span style={{
                fontFamily: 'var(--font-display)',
                fontWeight: 800,
                fontSize: '22px',
                color: 'var(--eco-text)',
                letterSpacing: '-0.5px'
              }}>EcoTrack</span>
            </div>
            <p style={{ fontSize: '14px', color: 'var(--eco-text-secondary)', lineHeight: '1.6' }}>
              Revolutionizing waste management through smart technology for a sustainable and <strong>Cleaner India</strong>. 🇮🇳
            </p>
          </div>

          {/* Platform Navigation */}
          <div>
            <div style={sectionHeaderStyle}>Platform</div>
            {[
              { to: '/', label: 'Home' },
              { to: '/how-it-works', label: 'How It Works' },
              { to: '/rewards', label: 'Rewards & Points' },
              { to: '/about', label: 'Our Mission' },
            ].map(l => (
              <Link
                key={l.to}
                to={l.to}
                style={linkStyle}
                onMouseEnter={e => e.target.style.color = 'var(--eco-primary)'}
                onMouseLeave={e => e.target.style.color = 'var(--eco-text-secondary)'}
              >{l.label}</Link>
            ))}
          </div>

          {/* Community Section */}
          <div>
            <div style={sectionHeaderStyle}>Community</div>
            {[
              { to: '/blogs', label: 'Environmental Blogs' },
              { to: '/campaigns', label: 'Active Campaigns' },
              { to: '/events', label: 'Local Events' },
            ].map(l => (
              <Link
                key={l.to}
                to={l.to}
                style={linkStyle}
                onMouseEnter={e => e.target.style.color = 'var(--eco-primary)'}
                onMouseLeave={e => e.target.style.color = 'var(--eco-text-secondary)'}
              >{l.label}</Link>
            ))}
          </div>

          {/* Account & Support */}
          <div>
            <div style={sectionHeaderStyle}>Support</div>
            {[
              { to: '/login', label: 'Partner Login' },
              { to: '/register', label: 'Join Movement' },
              { to: '/contact', label: 'Help Center' },
            ].map(l => (
              <Link
                key={l.to}
                to={l.to}
                style={linkStyle}
                onMouseEnter={e => e.target.style.color = 'var(--eco-primary)'}
                onMouseLeave={e => e.target.style.color = 'var(--eco-text-secondary)'}
              >{l.label}</Link>
            ))}
          </div>
        </div>

        {/* Bottom Bar */}
        <div style={{
          borderTop: '1px solid var(--eco-border)',
          paddingTop: '24px',
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          flexWrap: 'wrap',
          gap: '16px'
        }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
            <span style={{ fontSize: '13px', color: 'var(--eco-text-muted)' }}>
              © 2026 EcoTrack Solutions.
            </span>
            <span style={{ height: '12px', width: '1px', background: 'var(--eco-border)' }}></span>
            <span style={{ fontSize: '13px', color: 'var(--eco-text-muted)', display: 'flex', alignItems: 'center', gap: '4px' }}>
              Made in India 🇮🇳
            </span>
          </div>

          <div style={{ fontSize: '13px', color: 'var(--eco-text-muted)', fontWeight: 500 }}>
            Swachh Bharat • Abhiyan 🌱
          </div>
        </div>
      </div>
    </footer>
  );
};

export default Footer;
